/**
 * Route middleware (Starlight route data).
 *
 * The API reference generated by starlight-openapi has one page per
 * operation (200+). Its sidebar group is useful while browsing the
 * reference, but on every other page it would add hundreds of links to the
 * HTML (≈120 KB per page). Outside the reference the group is replaced by a
 * single link to the reference index; inside it, it is left untouched.
 */
import { defineRouteMiddleware, type StarlightRouteData } from '@astrojs/starlight/route-data';
import { API_REFERENCE_BASE } from './lib/constants.mjs';

type SidebarEntry = StarlightRouteData['sidebar'][number];

const isReferenceGroup = (e: SidebarEntry, prefix: string): boolean =>
  e.type === 'group' &&
  e.entries.length > 0 &&
  e.entries.every((c) => (c.type === 'link' ? c.href.startsWith(prefix) : isReferenceGroup(c, prefix)));

function collapseReference(entries: SidebarEntry[], prefix: string): SidebarEntry[] {
  return entries.map((e) => {
    if (e.type !== 'group') return e;
    if (isReferenceGroup(e, prefix)) {
      return { type: 'link', label: e.label, href: prefix, isCurrent: false, badge: e.badge, attrs: {} };
    }
    return { ...e, entries: collapseReference(e.entries, prefix) };
  });
}

export const onRequest = defineRouteMiddleware(async (context, next) => {
  // Let starlight-openapi build its sidebar first.
  await next();
  const base = import.meta.env.BASE_URL.replace(/\/$/, '');
  const route = context.locals.starlightRoute;
  const localePrefix = route.locale ? `/${route.locale}` : '';
  const prefix = `${base}/${API_REFERENCE_BASE}/`;
  const path = context.url.pathname;
  if (path.startsWith(prefix) || path.startsWith(`${base}${localePrefix}/${API_REFERENCE_BASE}/`)) return;
  route.sidebar = collapseReference(route.sidebar, prefix);
});
